package fi.alavesa.radio.hud;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.TextComponent;
import net.kyori.adventure.text.format.ShadowColor;
import net.kyori.adventure.text.format.TextColor;

/**
 * Lays the radio popup out inside ONE text component (the name of a boss bar).
 *
 * <p>How it works (font radio:hud, generated by tools/gen_pack.py; shaders/include/radio_text_*.glsl):
 * <ul>
 *   <li>every character of the font advances exactly {@link #ADVANCE} px (monospace by construction), and the font
 *       has signed spaces of ±2^n px, so the pen can be put anywhere;</li>
 *   <li>the component always ends with the pen back at 0: its width is 0, so the client's centring puts pen 0 at
 *       the screen centre, and the text shader moves every glyph from there into the corner;</li>
 *   <li>the text colour is the marker #FEFBxx: blue bits 0-3 = line (15 = art), bits 4-6 = palette or art flags.
 *       Shadows are off, or a dark copy of every glyph would stay behind at the top of the screen.</li>
 * </ul>
 * The geometry constants mirror tools/gen_pack.py.
 */
public final class HudText {

    public static final Key FONT = Key.key("radio", "hud");
    public static final int ADVANCE = 6;
    /** Characters per line, and the lines: header, id, {@link #MESSAGE_LINES} message lines, two hint lines. */
    public static final int COLUMNS = 28;
    public static final int LINE_HEADER = 0, LINE_ID = 1, LINE_MESSAGES = 2, MESSAGE_LINES = 5, LINE_HINT_1 = 7, LINE_HINT_2 = 8;
    public static final int GREEN = 0, WHITE = 1, AMBER = 2, RED = 3, GREY = 4, CYAN = 5, DIM = 6, YELLOW = 7;
    /** Art flags. */
    public static final int PANEL = 0, PANEL_STATIC = 1, LAMP = 2;

    public static final char DOT = '', ARROW = '', BLOCK = '';

    private static final int ART_LINE = 15;
    private static final int TEXT_X = 4, PANEL_W = 176, LAMP_X = 150, LAMP_W = 22;
    private static final char CHAR_PANEL = '', CHAR_LAMP = '';
    private static final char SPACE_POS = '', SPACE_NEG = '';
    /** What the font sheet has besides A-Z, 0-9 and ASCII punctuation up to '_'. */
    private static final String EXTRA = "ÄÖÅÜÉ" + DOT + ARROW + BLOCK;

    /** The RGB palette of radio_text_fragment.glsl, for picking the nearest entry to a channel's colour. */
    private static final int[] PALETTE_RGB = {0x7DFF99, 0xF2F7F2, 0xFFC240, 0xFF5445, 0x8C9E8F, 0x73E6FF, 0x428552, 0xFFF266};

    private final List<Component> parts = new ArrayList<>();
    private int pen;

    /** The panel background; {@code incoming} adds static while a transmission comes in. Call first. */
    public HudText panel(boolean incoming) {
        return art(0, CHAR_PANEL, PANEL_W, incoming ? PANEL_STATIC : PANEL);
    }

    /** The lit TX/RX lamp in the header. */
    public HudText lamp() {
        return art(LAMP_X, CHAR_LAMP, LAMP_W, LAMP);
    }

    private HudText art(int x, char glyph, int width, int flags) {
        parts.add(Component.text(shift(x - pen) + glyph, marker(ART_LINE, flags)).font(FONT).shadowColor(ShadowColor.none()));
        pen = x + width + 1;
        return this;
    }

    /** Text starting at a column (0 = the left text edge). It is cut at the right edge. */
    public HudText text(int line, int column, String text, int palette) {
        String s = sanitize(text);
        if (column < 0 || column >= COLUMNS || s.isEmpty()) return this;
        if (s.length() > COLUMNS - column) s = s.substring(0, COLUMNS - column);
        int x = TEXT_X + column * ADVANCE;
        parts.add(Component.text(shift(x - pen) + s, marker(line, palette)).font(FONT).shadowColor(ShadowColor.none()));
        pen = x + s.length() * ADVANCE;
        return this;
    }

    /** Text ending at the right edge. */
    public HudText right(int line, String text, int palette) {
        String s = sanitize(text);
        if (s.length() > COLUMNS) s = s.substring(0, COLUMNS);
        return text(line, COLUMNS - s.length(), s, palette);
    }

    public Component build() {
        TextComponent.Builder out = Component.text();
        for (Component part : parts) out.append(part);
        // back to pen 0: the whole component is then 0 px wide (see the class comment)
        out.append(Component.text(shift(-pen)).font(FONT));
        return out.build();
    }

    private static TextColor marker(int line, int data) {
        return TextColor.color(254, 251, (line & 15) | ((data & 7) << 4));
    }

    private static String shift(int px) {
        StringBuilder out = new StringBuilder();
        char base = px < 0 ? SPACE_NEG : SPACE_POS;
        int n = Math.abs(px);
        for (int bit = 9; bit >= 0; bit--) if ((n & (1 << bit)) != 0) out.append((char) (base + bit));
        return out.toString();
    }

    /**
     * What the popup font can show: capitals, digits, common punctuation and a few accented capitals. Lower case
     * becomes upper case; anything else becomes '?'. So every character is exactly one cell wide.
     */
    public static String sanitize(String text) {
        String upper = text.toUpperCase(Locale.ROOT);
        StringBuilder out = new StringBuilder(upper.length());
        for (int i = 0; i < upper.length(); i++) {
            char ch = upper.charAt(i);
            if (ch >= 0x20 && ch < 0x60 || EXTRA.indexOf(ch) >= 0) out.append(ch);
            else if (ch == '{') out.append('(');
            else if (ch == '}') out.append(')');
            else if (ch == '`' || ch == '´' || ch == '’' || ch == '‘') out.append('\'');
            else if (ch == '~' || ch == '–' || ch == '—') out.append('-');
            else if (ch == '“' || ch == '”') out.append('"');
            else if (!Character.isLowSurrogate(ch)) out.append('?');
        }
        return out.toString();
    }

    /** The palette entry closest to an RGB colour (for channel names). */
    public static int nearestPalette(int rgb) {
        int best = 0;
        long bestDistance = Long.MAX_VALUE;
        for (int i = 0; i < PALETTE_RGB.length; i++) {
            if (i == DIM || i == GREY) continue; // too faint for a name
            long dr = ((rgb >> 16) & 255) - ((PALETTE_RGB[i] >> 16) & 255), dg = ((rgb >> 8) & 255) - ((PALETTE_RGB[i] >> 8) & 255),
                    db = (rgb & 255) - (PALETTE_RGB[i] & 255);
            long d = dr * dr + dg * dg + db * db;
            if (d < bestDistance) {
                bestDistance = d;
                best = i;
            }
        }
        return best;
    }

    /** Breaks "prefix + text" into lines of {@link #COLUMNS}; continuation lines are indented by one column. */
    public static List<String> wrap(String text) {
        List<String> lines = new ArrayList<>();
        String rest = sanitize(text).strip();
        boolean first = true;
        while (!rest.isEmpty()) {
            int width = first ? COLUMNS : COLUMNS - 1;
            if (rest.length() <= width) {
                lines.add((first ? "" : " ") + rest);
                break;
            }
            int cut = rest.lastIndexOf(' ', width);
            if (cut < width / 2) cut = width; // a very long word: cut it
            lines.add((first ? "" : " ") + rest.substring(0, cut).stripTrailing());
            rest = rest.substring(cut).stripLeading();
            first = false;
        }
        return lines;
    }
}
